import sys,json,importlib.metadata as m,hashlib,pathlib,site
packages={d.metadata['Name']:{'version':d.version,'location':str(d.locate_file('')),'direct_url':d.read_text('direct_url.json')} for d in m.distributions()}
native={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in pathlib.Path(sys.prefix).rglob('_internal*.pyd')}
print(json.dumps({'python':sys.version,'prefix':sys.prefix,'base_prefix':sys.base_prefix,'sys_path':sys.path,'user_site_enabled':site.ENABLE_USER_SITE,'packages':packages,'native_sha256':native},indent=2))

